504	// Proposal 返回当前轮次本地提议；尚未提议时第二个返回值为 false。
505	// 重复调用、登记其他候选均不改变本地提议。
506	func (n *Node) Proposal() (ProposalView, bool) {
507		n.mu.Lock()
508		defer n.mu.Unlock()
509		rs := n.st.currentRoundState()
510		if rs == nil || rs.LocalBlockID == "" {
511			return ProposalView{}, false
512		}
513		return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), true
514	}
515	
516	func proposalViewOf(round uint64, c *candidateState) ProposalView {
517		ids := append([]string(nil), c.TxIDs...)
518		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
519	}
520	
521	// Propose 返回当前轮次唯一的本地提议；重复请求返回同一提议。
522	// 提议生成后即冻结：此后新提交的交易或新登记的候选都不改变该提议，
523	// 提议中的交易禁止替换。其他候选用 RegisterCandidate 另行登记。
524	func (n *Node) Propose() (ProposalView, error) {
525		n.mu.Lock()
526		defer n.mu.Unlock()
527		if rs := n.st.currentRoundState(); rs != nil && rs.LocalBlockID != "" {
528			return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), nil
529		}
530	
531		st := n.st.clone()
532		rs := st.Rounds[st.Round]
533		if rs == nil {
534			rs = &roundState{
535				Round:      st.Round,
536				Height:     uint64(len(st.Blocks)) + 1,
537				PreviousID: st.LastBlock,
538				Candidates: map[string]*candidateState{},
539			}
540			st.Rounds[st.Round] = rs
541		}
542		txIDs := st.selectTransactions()
543		blockID := BlockID(st.Round, rs.Height, rs.PreviousID, txIDs)
544		c := &candidateState{
545			TxIDs:   txIDs,
546			BlockID: blockID,
547			Votes:   []string{},
548			Local:   true,
549		}
550		rs.Candidates[blockID] = c
551		rs.LocalBlockID = blockID
552		for _, id := range txIDs {
553			st.Entries[id].Status = stProposed
554		}
555		if err := n.save(st); err != nil {
556			return ProposalView{}, err
557		}
558		n.st = st
559		return proposalViewOf(rs.Round, c), nil
560	}
