578	// RegisterResult 是候选登记结果。
579	type RegisterResult struct {
580		// BlockID 候选区块标识（沿用稳定区块标识编码）。
581		BlockID string
582		// Existing 为 true 时表示相同交易列表此前已登记，本次返回同一候选并保留已有票数。
583		Existing bool
584	}
585	
586	// RegisterCandidate 在当前轮次本地提议已产生且尚未确认时，按给定交易顺序登记一个
587	// 竞争候选，与本地提议一起参与投票。候选使用当前轮次与下一高度，接在最新确认块之后。
588	//
589	// 候选只能包含当前池内排队或已提议的交易，数量不得超过单块上限，允许空块；
590	// 列表不能重复交易；每个账户在列表中的序号必须从该账户已确认序号加一开始连续递增，
591	// 不同账户之间的顺序由调用者决定。相同列表重复登记返回同一候选并保留已有票数。
592	//
593	// 未产生本地提议、轮次不是当前轮次、引用未知或已退出池的交易、超过上限或序号
594	// 不连续时登记失败并返回带具体 Reason 的 *RejectError，节点状态不变。
595	func (n *Node) RegisterCandidate(round uint64, txIDs []string) (*RegisterResult, error) {
596		n.mu.Lock()
597		defer n.mu.Unlock()
598	
599		rs := n.st.currentRoundState()
600		// 轮次优先判定：非当前轮次不能登记，即使当前轮次尚未产生本地提议。
601		if round != n.st.Round {
602			return nil, reject(ReasonWrongRound, "candidate round %d does not match current round %d", round, n.st.Round)
603		}
604		if rs == nil || rs.LocalBlockID == "" {
605			return nil, reject(ReasonNoProposal, "round %d has no local proposal yet", n.st.Round)
606		}
607	
608		ids := append([]string{}, txIDs...)
609		if uint64(len(ids)) > n.st.MaxTxs {
610			return nil, reject(ReasonTooManyTxs, "candidate contains %d transactions, max per block is %d", len(ids), n.st.MaxTxs)
611		}
612		// 列表内不得重复交易。
613		seen := make(map[string]struct{}, len(ids))
614		for _, id := range ids {
615			if _, dup := seen[id]; dup {
616				return nil, reject(ReasonDuplicateInList, "transaction %s appears more than once in candidate list", id)
617			}
618			seen[id] = struct{}{}
619			e, ok := n.st.Entries[id]
620			if !ok {
621				return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
622			}
623			// 必须仍在池中（排队或已被某未决候选引用）；已确认、被替换、已过期均已退出池。
624			if e.Status != stQueued && e.Status != stProposed {
625				return nil, reject(ReasonTxNotInPool, "transaction %s is not queued or proposed (status %s)", id, e.Status)
626			}
627			if !inPool(n.st, e.Tx.SenderHex(), e.Tx.Sequence, id) {
628				return nil, reject(ReasonTxNotInPool, "transaction %s has left the pool", id)
629			}
630		}
631		// 每个账户的序号必须从已确认序号加一开始连续递增。
632		seqsBySender := map[string][]uint64{}
633		for _, id := range ids {
634			e := n.st.Entries[id]
635			sender := e.Tx.SenderHex()
636			seqsBySender[sender] = append(seqsBySender[sender], e.Tx.Sequence)
637		}
638		senders := make([]string, 0, len(seqsBySender))
639		for sender := range seqsBySender {
640			senders = append(senders, sender)
641		}
642		sort.Strings(senders)
643		for _, sender := range senders {
644			seqs := seqsBySender[sender]
645			want := n.st.Accounts[sender] + 1
646			for i, seq := range seqs {
647				if seq != want {
648					return nil, reject(ReasonSequenceGap,
649						"sender %s candidate sequence at position %d is %d, want %d (must be consecutive starting at confirmed sequence + 1)",
650						sender, i, seq, want)
651				}
652				want++
653			}
654		}
655	
656		blockID := BlockID(rs.Round, rs.Height, rs.PreviousID, ids)
657		if existing, ok := rs.Candidates[blockID]; ok {
658			// 相同列表重复登记：返回同一候选，保留已有票数，节点状态不变。
659			return &RegisterResult{BlockID: existing.BlockID, Existing: true}, nil
660		}
661	
662		st := n.st.clone()
663		rs2 := st.Rounds[st.Round]
664		rs2.Candidates[blockID] = &candidateState{
665			TxIDs:   ids,
666			BlockID: blockID,
667			Votes:   []string{},
668		}
669		for _, id := range ids {
670			if st.Entries[id].Status == stQueued {
671				st.Entries[id].Status = stProposed
672			}
673		}
674		if err := n.save(st); err != nil {
675			return nil, err
676		}
677		n.st = st
678		return &RegisterResult{BlockID: blockID}, nil
679	}
680	
681	// inPool 判断标识 id 是否仍是池中某账户某序号的当前交易。
682	func inPool(st *state, sender string, seq uint64, id string) bool {
683		cur, ok := st.Pool[sender][seq]
684		return ok && cur == id
685	}
686	
687	// selectTransactions 执行确定性打包：
688	// 每轮从各账户“下一条可确认”的交易中选费用最高者，费用相同按交易标识字典序；
689	// 选入某账户后才继续考虑其后续序号，直到达到上限或没有可选交易。
690	func (n *state) selectTransactions() []string {
691		var picked []string
692		// 每个账户在本次打包中下一个可考虑的序号。
693		next := map[string]uint64{}
694		for sender := range n.Pool {
695			next[sender] = n.Accounts[sender] + 1
696		}
697		for uint64(len(picked)) < n.MaxTxs {
698			var bestID string
699			var bestFee uint64
700			var bestSet bool
701			// 遍历发送者名单需确定序：按发送者十六进制定序，保证选择只取决于费用与标识。
702			senders := make([]string, 0, len(n.Pool))
703			for s := range n.Pool {
704				senders = append(senders, s)
705			}
706			sort.Strings(senders)
707			for _, sender := range senders {
708				id, ok := n.Pool[sender][next[sender]]
709				if !ok {
710					continue
711				}
712				e := n.Entries[id]
713				if e.Status != stQueued {
714					continue
715				}
716				if !bestSet || e.Tx.Fee > bestFee || (e.Tx.Fee == bestFee && id < bestID) {
717					bestID = id
718					bestFee = e.Tx.Fee
719					bestSet = true
720				}
721			}
722			if !bestSet {
723				break
724			}
725			picked = append(picked, bestID)
726			next[n.Entries[bestID].Tx.SenderHex()]++
727		}
728		if picked == nil {
729			picked = []string{}
730		}
731		return picked
732	}
