// 投票阈值、重复投票、非法投票拒绝。
func TestVoting(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 10)
	p, _ := n.Propose()
	round := n.CurrentRound()

	// 名单外身份
	outsider := genKeys(t, 1)[0]
