	block, err := n.BlockAt(1)
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprint(block.TxIDs) != fmt.Sprint([]string{id}) {
		t.Fatalf("confirmed block txs = %v, want [%s]", block.TxIDs, id)
	}
	info, err := n.Tx(id)
	if err != nil {
		t.Fatal(err)
	}
