// 打包顺序由接受时的费用与交易标识决定：提交成功后调用方提高或降低手中
// 对象的费用，不改变原先的打包顺序；确认块包含的仍是成功提交返回的原标识。
func TestSubmitInputFeeEditsDoNotChangePackingOrder(t *testing.T) {
	keys := genKeys(t, 4)
